    font='SimHei' if heading else 'FangSong'
    for run in para.runs:
        run.font.name=font
        rf=run._element.get_or_add_rPr().rFonts
        for slot in ('ascii','hAnsi','eastAsia','cs'): rf.set(qn('w:'+slot),font)
for tbl in d.tables:
